-- One selected blog from each category that was not already represented in the project.
on conflict (id) do update set title=excluded.title,excerpt=excluded.excerpt,author=excluded.author,author_avatar=excluded.author_avatar,category=excluded.category,tags=excluded.tags,read_time=excluded.read_time,publish_date=excluded.publish_date,source_name=excluded.source_name,url=excluded.url,cover_image=excluded.cover_image,cover_alt=excluded.cover_alt,cover_fit=excluded.cover_fit,status=excluded.status,featured=excluded.featured;
